description:
Query approach
- Inefficient because you have to look up the tree repeatedly (the while loops with node_parent)
- Could use a more optimized query that also includes the `<-` in the query, but then you also have to handle the special case of `<- recipe() %>%`

Walk approach:
- Faster because it only does 1 pass over the tree
- A little inefficient because it could use `TreeCursor` instead (probably worth showing node api vs cursor api in the vignette)
- Produces less results than query approach so there is probably a bug somewhere

Goal: Find all `recipes()` calls in `tests/` that are outside a `test_that()` block and are part of an `<-` assignment operation

Example code below should be run in the recipes repo

```r
library(treesitter)

language <- treesitter.r::language()
PARSER <- parser(language)

# A query that finds all `recipe()` function calls
RECIPES_QUERY <- r"(
(
  (call
    function: (identifier) @function_name
  )
  (#eq? @function_name recipe)
)
)"
RECIPES_QUERY <- query(language, RECIPES_QUERY)

# Is this node a `<-` binary operator?
is_assignment_binary_operator <- function(node) {
  if (node_type(node) != "binary_operator") {
    return(FALSE)
  }

  child <- node_child_by_field_name(node, "operator")
  if (is.null(child)) {
    return(FALSE)
  }

  node_type(child) == "<-"
}

# Does this node have a parent that is a `<-` binary operator?
in_assignment <- function(node) {
  parent <- node_parent(node)
  while (!is.null(parent)) {
    if (is_assignment_binary_operator(parent)) {
      return(TRUE)
    }
    parent <- node_parent(parent)
  }
  FALSE
}

# Is this node a `test_that()` call?
is_test_that <- function(node) {
  if (node_type(node) != "call") {
    return(FALSE)
  }

  child <- node_child_by_field_name(node, "function")
  if (is.null(child)) {
    return(FALSE)
  }

  if (node_type(child) != "identifier") {
    return(FALSE)
  }

  node_text(child) == "test_that"
}

# Does this node have a parent that is a `test_that()` call?
in_test_that <- function(node) {
  parent <- node_parent(node)
  while (!is.null(parent)) {
    if (is_test_that(parent)) {
      return(TRUE)
    }
    parent <- node_parent(parent)
  }
  FALSE
}

find_recipes2 <- function(file) {
  text <- readLines(file) |>
    paste0(collapse = "\n")

  tree <- parser_parse(PARSER, text)
  node <- tree_root_node(tree)

  # Find all `recipe()` calls
  nodes <- query_captures(RECIPES_QUERY, node)[[2]]

  # Limit to ones we care about
  nodes <- Filter(x = nodes, function(node) {
    !in_test_that(node) && in_assignment(node)
  })

  # extract row number
  rows <- vapply(nodes, \(x) point_row(node_start_point(x)) + 1L, numeric(1))

  tibble::tibble(file = file, row = rows)
}

fs::dir_ls("tests/testthat/", regexp = "test-") |>
  purrr::map(find_recipes2) |>
  purrr::list_rbind() |>
  dplyr::mutate(path = paste0(file, ":", row))
```


```r
library(treesitter, warn.conflicts = FALSE)

language <- treesitter.r::language()
parser <- parser(language)

find_recipes <- function(file) {

  # Debugging
  # file <- fs::dir_ls("tests/testthat/", regexp = "test-")[[3]]

  # Read in test file
  text <- readLines(file) |>
    paste0(collapse = "\n")

  # Apply parser
  tree <- parser_parse(parser, text)

  # General idea. Go over each of the child nodes. Remove things one at a time,
  # untill be are left with something on the form `rec_name <- recipe(...)...`
  nodes <- tree |>
    tree_root_node() |>
    node_children()

  # Remove all `test_that()` nodes
  nodes <- nodes |>
    purrr::keep(function(x) {
      child <- node_child(x, 1)
      if (is.null(child)) {
        return(FALSE)
      }
      node_text(child) != "test_that"
    })

  # check that an assignment is happening
  nodes <- nodes |>
    purrr::keep(function(x) {
      if (node_type(x) != "binary_operator") {
        return(FALSE)
      }

      text <- node_child(x, 2) |> node_text()
      text %in% c("<-", "=")
    })

  # finding recipe calls
  nodes <- nodes |>
    purrr::keep(function(x) {
      node <- node_child(x, 3)

      if (is.null(node)) {
        return(FALSE)
      }
      node <- node_child(node, 1)

      if (is.null(node)) {
        return(FALSE)
      }
      # recipe() without %>%
      if (node_text(node) == "recipe") {
        return(TRUE)
      }
      node <- node_child(node, 1)

      if (is.null(node)) {
        return(FALSE)
      }
      # recipe() with %>%
      node_text(node) == "recipe"
    })

  # extract row number
  rows <- vapply(nodes, \(x) node_start_point(x)$row, numeric(1))

  tibble::tibble(file = file, row = rows)
}

fs::dir_ls("tests/testthat/", regexp = "test-") |>
  purrr::map(find_recipes) |>
  purrr::list_rbind() |>
  dplyr::mutate(path = paste0(file, ":", row))
```
